//! One declaration supplies the method table, owning module router, TS bindings and MCP exposure.
use crate::describe::{Declared, schema_of};
#[cfg(feature = "export")]
use crate::methods::Method;
use crate::methods::{ExportedMethod, typed};

/// F8, M16: the Bubble rule every Terminal-starting tool's description states, as the Brief does.
#[macro_export]
macro_rules! bubble_rule {
    () => {
        " Use your own tools for commands; open a Bubble only when the user needs to see its output or will interactively type into it. Routine builds, tests and inspection use your own tools."
    };
}

macro_rules! mcp_choice {
    (all($($tool:tt)*)) => {
        crate::methods::McpChoice::All
    };
    (door($($tool:tt)*)) => {
        crate::methods::McpChoice::Door
    };
    (none($reason:expr)) => {
        crate::methods::McpChoice::None($reason)
    };
}
macro_rules! perf_disposition {
    (measured($($metric:expr),+)) => { crate::methods::PerfDisposition::Measured(&[$($metric),+]) };
    (off_path($reason:expr)) => { crate::methods::PerfDisposition::OffPath($reason) };
}
macro_rules! method_text {
    (tool, $role:ident(schema($ty:ty, $description:expr))) => {
        $description
    };
    (tool, $role:ident(empty($description:expr))) => {
        $description
    };
    (text($description:expr), $role:ident($($tool:tt)*)) => {
        $description
    };
}

macro_rules! declarations {
    ($d:tt; $($owner:ident [$namespace:literal] { $($wire:literal: $params:ty => $result:ty, $handler:ident, $role:ident($($tool:tt)*), $perf:ident($($disposition:tt)*), $text:ident$(($description:expr))?; )* })*) => {
        #[cfg(feature = "export")]
        pub const METHODS: &[Method<'static>] = &[$($(Method {name: $wire, params: stringify!($params), result: stringify!($result)},)*)*];
        pub fn owner_namespace(method: &str) -> Option<&'static str> {
            match method { $($($wire => Some($namespace),)*)* _ => None }
        }
        pub(crate) fn exported() -> Vec<ExportedMethod> { vec![$($(typed::<$params, $result>($wire),)*)*] }
        pub fn metadata() -> Vec<crate::methods::Metadata> {
            vec![$($(crate::methods::Metadata { name: $wire, mcp: mcp_choice!($role($($tool)*)), perf: perf_disposition!($perf($($disposition)*)), description: method_text!($text$(($description))?, $role($($tool)*)), },)*)*]
        }
        pub(crate) fn declared() -> Vec<Declared> {
            vec![$($(Declared { name: $wire, description: method_text!($text$(($description))?, $role($($tool)*)), params: schema_of::<$params>, result: schema_of::<$result>, },)*)*]
        }
        pub(crate) fn types() -> specta::Types { specta::Types::default() $($(.register::<$params>().register::<$result>())*)* }
        $(
            #[macro_export]
            macro_rules! $owner {
                ($d($d callback:ident)::+, $d($d args:tt)*) => {
                    $d($d callback)::+! { [$d($d args)*] $($wire: $params => $result, $handler, $role($($tool)*);)* }
                };
            }
        )*
        #[macro_export]
        macro_rules! all_methods {
            ($d($d callback:ident)::+) => {
                $d($d callback)::+! { [] $($($wire: $params => $result, $handler, $role($($tool)*);)*)* }
            };
        }
    };
}

